export function marineProtectionAt(input){const p=gpsValue(input);if(!p)return{supported:false,areas:[],uncertain:[],reason:'missing_gps'};const coverage=LOCAL_MPA_COVERAGE,supported=p.lon>=coverage.west&&p.lon<=coverage.east&&p.lat>=coverage.south&&p.lat<=coverage.north,areas=[],uncertain=[];for(const area of MPA_AREAS){const inside=area.rings.reduce((hit,ring)=>insideRing(p.lon,p.lat,ring)?!hit:hit,false),edgeMeters=boundaryDistance(p,area.rings);if(edgeMeters<=area.boundaryUncertaintyMeters)uncertain.push({id:area.id,name:area.name,edgeMeters,source:area.source});else if(inside)areas.push({id:area.id,name:area.name,type:area.type,source:area.source});}return{supported,areas,uncertain,reason:supported?null:'outside_local_mpa_coverage'};}
